from app.services.slm.base import SLMAdapter
import time

class MockSLMAdapter(SLMAdapter):
    def generate_workout_plan(self, user_profile: dict) -> dict:
        # Simulate processing delay
        time.sleep(1.5)
        
        goal = user_profile.get("fitness_goal", "general_fitness")
        
        # In a real scenario, this would be generated by the model.
        # Here we return a static mock structure that conforms to the schema.
        return {
            "goal": goal,
            "duration_days": 7,
            "workout_plan": [
                {
                    "day": "Monday",
                    "focus": "Full Body Strength",
                    "duration_minutes": 45,
                    "exercises": [
                        {
                            "name": "Squats" if goal in ["muscle_gain", "general_fitness"] else "Bodyweight Squats",
                            "sets": 4 if goal == "muscle_gain" else 3,
                            "reps": 8 if goal == "muscle_gain" else 15,
                            "rest_seconds": 90 if goal == "muscle_gain" else 45
                        },
                        {
                            "name": "Push-ups",
                            "sets": 3,
                            "reps": 12,
                            "rest_seconds": 60
                        }
                    ]
                }
            ]
        }
